      const j = jobs.get(id);
      if (!j) return refuse(`no job ${id}`);
      if (j.status !== 'held') return refuse(`job ${id} is ${j.status}, not held`);
      j.status = 'queued';
      return ok;
    },

    async job(id) {
      const j = jobs.get(id);
      return j ? { status: j.status, tries: j.tries, maxTries: j.maxTries } : null;
    },
  };
}

